/* Simplified from nginx ngx_http_range_parser(), pre-patch (CVE-2017-7529). */
/* 'start' and 'end' are parsed from the attacker's Range header. */
static ngx_int_t range_body(u_char *cache_data, off_t content_length,
                            off_t start, off_t end, ngx_http_request_t *r)
{
    if (end >= content_length)
        end = content_length;

    ngx_uint_t size = end - start;          /* unsigned subtraction */
    u_char *buf = ngx_pcalloc(r->pool, size);
    ngx_memcpy(buf, cache_data + start, size);
    return ngx_http_output(r, buf, size);
}

